1	#include "x11shim/stroke.h"
2	
3	#include <math.h>
4	#include <stdbool.h>
5	#include <stdint.h>
6	#include <stdlib.h>
7	
8	typedef int64_t wide_t;
9	typedef struct {
10	  float x, y;
11	} vec2;
12	
13	static wide_t min_w(wide_t a, wide_t b) { return a < b ? a : b; }
14	static wide_t max_w(wide_t a, wide_t b) { return a > b ? a : b; }
15	static wide_t clamp_w(wide_t v, wide_t lo, wide_t hi) {
16	  return v < lo ? lo : v > hi ? hi : v;
17	}
18	
19	static void fill_box(Canvas *c, wide_t x0, wide_t y0, wide_t x1, wide_t y1,
20	                     uint16_t colour);
21	
22	/* The rows of a disc of each diameter up to DISC_MAX_W, relative to its corner.
23	 * canvas_fill_ellipse works each row out in double precision, which the S3 does
24	 * in software, and a round-capped line draws two discs per segment. A disc's
25	 * rows do not depend on where it sits, so they are worked out once per width.
26	 * A row with xb < xa is empty. */
27	#define DISC_MAX_W 16
28	typedef struct {
29	  int16_t xa, xb;
30	} disc_row;
31	static disc_row g_disc_rows[DISC_MAX_W + 1][DISC_MAX_W];
32	static bool g_disc_built[DISC_MAX_W + 1];
33	
34	/* The same arithmetic as canvas_fill_ellipse, for an ellipse at the origin. */
35	static void build_disc(int w) {
36	  const double centre = (w - 1) / 2.0, radius = w / 2.0;
37	  for (int row = 0; row < w; row++) {
38	    const double ny = (row - centre) / radius;
39	    const double t = 1.0 - ny * ny;
40	    disc_row d = {0, -1};
41	    if (t >= 0) {
42	      const double half = radius * sqrt(t);
43	      const int xa = (int)ceil(centre - half), xb = (int)floor(centre + half);
44	      if (xb >= xa) d = (disc_row){(int16_t)xa, (int16_t)xb};
45	    }
46	    g_disc_rows[w][row] = d;
47	  }
48	  g_disc_built[w] = true;
49	}
50	
51	/* The alpha of the GC being drawn with, set at each public entry point. */
52	static int g_alpha;
53	
54	/* A disc wider than the cached rows, with the same arithmetic, drawn through
55	 * fill_box so it blends or sets mask bits like the rest of its shape. Only
56	 * the rows on the canvas are worked out. */
57	static void wide_disc_rows(Canvas *c, wide_t x, wide_t y, int w, uint16_t colour) {
58	  const double centre = (w - 1) / 2.0, radius = w / 2.0;
59	  const wide_t first = max_w(0, -y), last = min_w(w - 1, (wide_t)c->h - 1 - y);
60	  for (wide_t row = first; row <= last; row++) {
61	    const double ny = ((double)row - centre) / radius;
62	    const double t = 1.0 - ny * ny;
63	    if (t < 0) continue;
64	    const double half = radius * sqrt(t);
65	    const wide_t xa = (wide_t)ceil(centre - half), xb = (wide_t)floor(centre + half);
66	    if (xb >= xa) fill_box(c, x + xa, y + row, x + xb, y + row, colour);
67	  }
68	}
69	
70	/* A disc of diameter w centred on the pixel (cx, cy). Skipped when it cannot
71	 * reach the canvas. */
72	static void disc(Canvas *c, wide_t cx, wide_t cy, int w, uint16_t colour) {
73	  if (cx < -(wide_t)w || cy < -(wide_t)w || cx > (wide_t)c->w + w ||
74	      cy > (wide_t)c->h + w)
75	    return;
76	  const wide_t x = cx - w / 2, y = cy - w / 2;
77	  if (w > DISC_MAX_W && g_alpha) {
78	    wide_disc_rows(c, x, y, w, colour);
79	    return;
80	  }
81	  if (w < 1 || w > DISC_MAX_W) {
82	    canvas_fill_ellipse(c, (int)x, (int)y, w, w, colour);
83	    return;
84	  }
85	  if (!g_disc_built[w]) build_disc(w);
86	  for (int row = 0; row < w; row++) {
87	    const disc_row d = g_disc_rows[w][row];
88	    if (d.xb >= d.xa) fill_box(c, x + d.xa, y + row, x + d.xb, y + row, colour);
89	  }
90	}
91	
92	static uint16_t swap16(uint16_t v) { return (uint16_t)((v << 8) | (v >> 8)); }
93	
94	/* Red and blue in bits 0-4 and 11-15, green in bits 21-26, so one multiply
95	 * scales all three channels and the gaps take the carries. */
96	#define SPREAD_MASK 0x07E0F81Fu
97	static uint32_t spread(uint16_t v) { return ((uint32_t)v | ((uint32_t)v << 16)) & SPREAD_MASK; }
98	static uint16_t unspread(uint32_t v) { return (uint16_t)((v & 0xFFFFu) | (v >> 16)); }
99	
100	/* The canvas holds byte-swapped RGB565, so each pixel is swapped to blend and
101	 * swapped back. The box is already clipped. */
102	static void blend_box(Canvas *c, int x, int y, int w, int h, uint16_t colour) {
103	  const uint32_t src = spread(swap16(colour));
104	  const uint32_t a = (uint32_t)g_alpha;
105	  for (int yy = y; yy < y + h; yy++) {
106	    uint16_t *row = c->px + (size_t)yy * c->w + x;
107	    for (int i = 0; i < w; i++) {
108	      const uint32_t dst = spread(swap16(row[i]));
109	      row[i] = swap16(unspread((((src - dst) * a >> 5) + dst) & SPREAD_MASK));
110	    }
111	  }
112	  canvas_mark_dirty(c, x, y, w, h);
113	}
114	
115	/* A shape made of overlapping pieces (a polyline's segments and joins, a
116	 * round cap and its segment) would blend twice where they overlap. While a
117	 * mask is open, pieces only set bits in it, one per pixel of the canvas, and
118	 * close_mask blends each set pixel once. */
119	static uint32_t *g_mask;
120	static int g_mask_words;
121	
122	static void open_mask(const Canvas *c) {
123	  g_mask_words = (c->w + 31) / 32;
124	  g_mask = (uint32_t *)calloc((size_t)g_mask_words * (size_t)c->h, sizeof(uint32_t));
125	}
126	
127	static void mask_row(int y, int x0, int x1) {
128	  uint32_t *row = g_mask + (size_t)y * g_mask_words;
129	  for (int w = x0 / 32; w <= x1 / 32; w++) {
130	    const int lo = w == x0 / 32 ? x0 % 32 : 0;
131	    const int hi = w == x1 / 32 ? x1 % 32 : 31;
132	    const uint32_t bits = (hi == 31 ? ~0u : (1u << (hi + 1)) - 1u) & (~0u << lo);
133	    row[w] |= bits;
134	  }
135	}
136	
137	static void close_mask(Canvas *c, uint16_t colour) {
138	  if (!g_mask) return;
139	  uint32_t *mask = g_mask;
140	  g_mask = NULL;
141	  for (int y = 0; y < c->h; y++) {
142	    const uint32_t *row = mask + (size_t)y * g_mask_words;
143	    for (int w = 0; w < g_mask_words; w++) {
144	      uint32_t bits = row[w];
145	      while (bits) {
146	        const int start = __builtin_ctz(bits);
147	        const uint32_t shifted = bits >> start;
148	        const int len = shifted == ~0u >> start ? 32 - start : __builtin_ctz(~shifted);
149	        blend_box(c, w * 32 + start, y, len, 1, colour);
150	        bits = start + len >= 32 ? 0 : bits & (~0u << (start + len));
151	      }
152	    }
153	  }
154	  free(mask);
155	}
156	
157	/* Fills x0..x1 by y0..y1 (inclusive), clipped to the canvas first so the
158	 * ints handed on are small. */
159	static void fill_box(Canvas *c, wide_t x0, wide_t y0, wide_t x1, wide_t y1,
160	                     uint16_t colour) {
161	  x0 = max_w(x0, 0);
162	  y0 = max_w(y0, 0);
163	  x1 = min_w(x1, (wide_t)c->w - 1);
164	  y1 = min_w(y1, (wide_t)c->h - 1);
165	  if (x0 > x1 || y0 > y1) return;
166	  if (g_mask) {
167	    for (wide_t y = y0; y <= y1; y++) mask_row((int)y, (int)x0, (int)x1);
168	    return;
169	  }
170	  if (g_alpha) {
171	    blend_box(c, (int)x0, (int)y0, (int)(x1 - x0 + 1), (int)(y1 - y0 + 1), colour);
172	    return;
173	  }
174	  canvas_fill_rect(c, (int)x0, (int)y0, (int)(x1 - x0 + 1), (int)(y1 - y0 + 1),
175	                   colour);
176	}
177	
178	/* Axis-aligned segment as one rectangle, caps included. */
179	static void axis_aligned(Canvas *c, wide_t x1, wide_t y1, wide_t x2, wide_t y2,
180	                         int cap1, int cap2, int w, uint16_t colour) {
181	  const wide_t before = w / 2;
182	  const wide_t ext = w / 2;
183	  if (y1 == y2) {
184	    const int lo_cap = x1 <= x2 ? cap1 : cap2, hi_cap = x1 <= x2 ? cap2 : cap1;
185	    const wide_t xa = min_w(x1, x2) - (lo_cap == CapProjecting ? ext : 0);
186	    const wide_t xb = max_w(x1, x2) + (hi_cap == CapProjecting ? ext : 0);
187	    fill_box(c, xa, y1 - before, xb, y1 - before + w - 1, colour);
188	  } else {
189	    const int lo_cap = y1 <= y2 ? cap1 : cap2, hi_cap = y1 <= y2 ? cap2 : cap1;
190	    const wide_t ya = min_w(y1, y2) - (lo_cap == CapProjecting ? ext : 0);
191	    const wide_t yb = max_w(y1, y2) + (hi_cap == CapProjecting ? ext : 0);
192	    fill_box(c, x1 - before, ya, x1 - before + w - 1, yb, colour);
193	  }
194	}
195	
196	/* Clips the segment to the canvas grown by margin, in double, because the
197	 * ends can be anywhere in the int range. Returns 0 when nothing is left. */
198	static int clip_to_canvas(const Canvas *c, wide_t margin, double *x1,
199	                          double *y1, double *x2, double *y2) {
200	  const double xmin = -(double)margin, xmax = (double)c->w + margin;
201	  const double ymin = -(double)margin, ymax = (double)c->h + margin;
202	  const double dx = *x2 - *x1, dy = *y2 - *y1;
203	  const double p[4] = {-dx, dx, -dy, dy};
204	  const double q[4] = {*x1 - xmin, xmax - *x1, *y1 - ymin, ymax - *y1};
205	  double t0 = 0, t1 = 1;
206	  for (int i = 0; i < 4; i++) {
207	    if (p[i] == 0) {
208	      if (q[i] < 0) return 0;
209	    } else {
210	      const double t = q[i] / p[i];
211	      if (p[i] < 0) {
212	        if (t > t1) return 0;
213	        if (t > t0) t0 = t;
214	      } else {
215	        if (t < t0) return 0;
216	        if (t < t1) t1 = t;
217	      }
218	    }
219	  }
220	  const double ax = *x1 + t0 * dx, ay = *y1 + t0 * dy;
221	  const double bx = *x1 + t1 * dx, by = *y1 + t1 * dy;
222	  *x1 = ax;
223	  *y1 = ay;
224	  *x2 = bx;
225	  *y2 = by;
226	  return 1;
227	}
228	
229	/* A pixel centre exactly on an edge that two polygons share (a 45 degree edge
230	 * through integer vertices passes through pixel centres) belongs to the one
231	 * on its left. Float error of a few millionths in an edge's x can drop it from
232	 * both and leave a hole in a wide arc, so a right edge is inclusive to within
233	 * this much (issue #56). */
234	#define EDGE_SLACK 1e-3f
235	
236	/* Fills a convex polygon whose vertices are in pixel coordinates, where the
237	 * pixel at x, y has its centre at x + 0.5, y + 0.5. A pixel is drawn when its
238	 * centre is inside, the left and top edges excluded and the right and bottom
239	 * edges included. The vertices stay floats: canvas_fill_polygon takes ints,
240	 * which would move the edges of a thin line by up to half a pixel. */
241	static void fill_convex(Canvas *c, const float pts[][2], int n,
242	                        uint16_t colour) {
243	  float ymin = pts[0][1], ymax = ymin;
244	  for (int i = 1; i < n; i++) {
245	    ymin = fminf(ymin, pts[i][1]);
246	    ymax = fmaxf(ymax, pts[i][1]);
247	  }
248	  const wide_t y0 = max_w(0, (wide_t)floorf(ymin));
249	  const wide_t y1 = min_w((wide_t)c->h - 1, (wide_t)ceilf(ymax));
250	  for (wide_t y = y0; y <= y1; y++) {
251	    const float sy = (float)y + 0.5f;
252	    float xl = INFINITY, xr = -INFINITY;
253	    for (int i = 0, j = n - 1; i < n; j = i++) {
254	      const float yi = pts[i][1], yj = pts[j][1];
255	      if ((yi < sy && yj >= sy) || (yj < sy && yi >= sy)) {
256	        const float x = pts[i][0] + (sy - yi) / (yj - yi) * (pts[j][0] - pts[i][0]);
257	        xl = fminf(xl, x);
258	        xr = fmaxf(xr, x);
259	      }
260	    }
261	    if (xl > xr) continue;
262	    fill_box(c, (wide_t)floorf(xl - 0.5f) + 1, y,
263	             (wide_t)floorf(xr - 0.5f + EDGE_SLACK), y, colour);
264	  }
265	}
266	
267	/* Where a vertex's line runs, in pixel coordinates (see stroke.h). */
268	static float centre_offset(int w) { return (w & 1) ? 0.5f : 0.0f; }
269	
270	static vec2 vertex(int x, int y, int w) {
271	  const float o = centre_offset(w);
272	  return (vec2){(float)x + o, (float)y + o};
273	}
274	
275	/* A segment between two vertices already in pixel coordinates, as a quad. An
276	 * end with a butt or round cap is lengthened enough to cover the pixel at the
277	 * vertex (half a pixel on an axis-aligned line; up to 0.71 on a diagonal when
278	 * the width is even and the vertex is a pixel corner). A projecting cap is
279	 * half the width past the vertex. An end that meets another segment
280	 * (STROKE_NO_CAP) is not lengthened at all. */
281	static void segment_quad(Canvas *c, vec2 a, vec2 b, int cap1, int cap2, int w,
282	                         uint16_t colour) {
283	  const float dx = b.x - a.x, dy = b.y - a.y;
284	  const float len = sqrtf(dx * dx + dy * dy);
285	  if (len < 0.001f) return;
286	  const float ux = dx / len, uy = dy / len;
287	  const float half = (float)w / 2.0f;
288	  const float pixel_along = (0.5f - centre_offset(w)) * (ux + uy);
289	  /* A butt cap must reach the vertex pixel (at least half a pixel). A
290	   * projecting cap reaches half the width past the vertex, which covers it,
291	   * plus the vertex pixel's offset when that is past the vertex. */
292	  const float e1 = cap1 == STROKE_NO_CAP     ? 0.0f
293	                   : cap1 == CapProjecting   ? half + fmaxf(0.0f, -pixel_along)
294	                                             : fmaxf(0.5f, -pixel_along);
295	  const float e2 = cap2 == STROKE_NO_CAP     ? 0.0f
296	                   : cap2 == CapProjecting   ? half + fmaxf(0.0f, pixel_along)
297	                                             : fmaxf(0.5f, pixel_along);
298	  const float nx = -uy * half, ny = ux * half;
299	  const vec2 p = {a.x - ux * e1, a.y - uy * e1};
300	  const vec2 q = {b.x + ux * e2, b.y + uy * e2};
301	  const float quad[4][2] = {
302	      {p.x + nx, p.y + ny}, {q.x + nx, q.y + ny}, {q.x - nx, q.y - ny},
303	      {p.x - nx, p.y - ny}};
304	  fill_convex(c, quad, 4, colour);
305	}
306	
307	/* One slanted segment whose ends can be anywhere in the int range. Ends cut by
308	 * the clip are off screen anyway. */
309	static void slanted(Canvas *c, wide_t ix1, wide_t iy1, wide_t ix2, wide_t iy2,
310	                    int cap1, int cap2, int w, uint16_t colour) {
311	  /* The clip is in double, which the S3 does in software, and floats are exact
312	   * well past any canvas, so only ends far outside need it. */
313	  const wide_t near = (wide_t)1 << 20;
314	  const int small = ix1 > -near && ix1 < near && iy1 > -near && iy1 < near &&
315	                    ix2 > -near && ix2 < near && iy2 > -near && iy2 < near;
316	  const float o = centre_offset(w);
317	  if (small) {
318	    /* Straight from int: an int under 2^20 is exact as a float, so this is
319	     * what the double detour gave, without four int64-to-double and four
320	     * double-to-float calls a segment. */
321	    segment_quad(c, (vec2){(float)(int)ix1 + o, (float)(int)iy1 + o},
322	                 (vec2){(float)(int)ix2 + o, (float)(int)iy2 + o}, cap1, cap2, w, colour);
323	    return;
324	  }
325	  double x1 = (double)ix1, y1 = (double)iy1, x2 = (double)ix2, y2 = (double)iy2;
326	  if (!clip_to_canvas(c, (wide_t)w + 2, &x1, &y1, &x2, &y2)) return;
327	  segment_quad(c, (vec2){(float)x1 + o, (float)y1 + o},
328	               (vec2){(float)x2 + o, (float)y2 + o}, cap1, cap2, w, colour);
329	}
330	
331	static void segment_pieces(Canvas *c, const struct XshimGC *gc, int x1, int y1,
332	                           int x2, int y2, int cap_start, int cap_end) {
333	  const int w = gc->line_width;
334	  const uint16_t colour = (uint16_t)gc->foreground;
335	
336	  if (cap_start == CapRound) disc(c, x1, y1, w, colour);
337	  if (cap_end == CapRound) disc(c, x2, y2, w, colour);
338	
339	  if (x1 == x2 && y1 == y2) {
340	    if (cap_start == CapProjecting || cap_end == CapProjecting)
341	      axis_aligned(c, x1, y1, x2, y2, cap_start, cap_end, w, colour);
342	    return;
343	  }
344	  if (x1 == x2 || y1 == y2)
345	    axis_aligned(c, x1, y1, x2, y2, cap_start, cap_end, w, colour);
346	  else
347	    slanted(c, x1, y1, x2, y2, cap_start, cap_end, w, colour);
348	}
349	
350	/* Only a round cap overlaps the segment's own body. */
351	void stroke_segment_ends(Canvas *c, const struct XshimGC *gc, int x1, int y1,
352	                         int x2, int y2, int cap_start, int cap_end) {
353	  g_alpha = gc->alpha;
354	  const int overlaps = cap_start == CapRound || cap_end == CapRound;
355	  if (g_alpha && overlaps) open_mask(c);
356	  segment_pieces(c, gc, x1, y1, x2, y2, cap_start, cap_end);
357	  close_mask(c, (uint16_t)gc->foreground);
358	}
359	
360	void stroke_segment(Canvas *c, const struct XshimGC *gc, int x1, int y1, int x2,
361	                    int y2) {
362	  stroke_segment_ends(c, gc, x1, y1, x2, y2, gc->cap_style, gc->cap_style);
363	}
364	
365	/* The corner between a segment arriving along d1 and one leaving along d2
366	 * (unit vectors), at vertex (ix, iy). */
367	static void join_at(Canvas *c, int ix, int iy, vec2 d1, vec2 d2, int w,
368	                    int style, uint16_t colour) {
369	  const float dot = d1.x * d2.x + d1.y * d2.y;
370	  const float cross = d1.x * d2.y - d1.y * d2.x;
371	  if (fabsf(cross) < 1e-4f && dot > 0) return;
372	  if (style == JoinRound) {
373	    disc(c, ix, iy, w, colour);
374	    return;
375	  }
376	  const vec2 v = vertex(ix, iy, w);
377	  const float half = (float)w / 2.0f;
378	  const float side = cross > 0 ? -1.0f : 1.0f;
379	  const vec2 n1 = {-d1.y * side, d1.x * side}, n2 = {-d2.y * side, d2.x * side};
380	  const vec2 p1 = {v.x + n1.x * half, v.y + n1.y * half};
381	  const vec2 p2 = {v.x + n2.x * half, v.y + n2.y * half};
382	  /* Xlib's miter limit of 10: the miter is longer than ten widths when the
383	   * segments meet at less than about 11.5 degrees, i.e. dot < -0.98. */
384	  if (style == JoinMiter && dot >= -0.98f) {
385	    const float k = half / (1.0f + dot);
386	    const float quad[4][2] = {{v.x, v.y},
387	                              {p1.x, p1.y},
388	                              {v.x + (n1.x + n2.x) * k, v.y + (n1.y + n2.y) * k},
389	                              {p2.x, p2.y}};
390	    fill_convex(c, quad, 4, colour);
391	    return;
392	  }
393	  const float tri[3][2] = {{v.x, v.y}, {p1.x, p1.y}, {p2.x, p2.y}};
394	  fill_convex(c, tri, 3, colour);
395	}
396	
397	void stroke_circle(Canvas *c, const struct XshimGC *gc, int x, int y, unsigned w) {
398	  const int lw = gc->line_width;
399	  const uint16_t colour = (uint16_t)gc->foreground;
400	  g_alpha = gc->alpha;
401	  const float o = centre_offset(lw);
402	  const float radius = (float)w / 2.0f;
403	  const float cx = (float)x + radius + o, cy = (float)y + radius + o;
404	  const float outer = radius + (float)lw / 2.0f;
405	  const float inner = radius - (float)lw / 2.0f;
406	  const wide_t y0 = max_w(0, (wide_t)floorf(cy - outer));
407	  const wide_t y1 = min_w((wide_t)c->h - 1, (wide_t)ceilf(cy + outer));
408	  for (wide_t row = y0; row <= y1; row++) {
409	    const float dy = (float)row + 0.5f - cy;
410	    if (fabsf(dy) >= outer) continue;
411	    const float ho = sqrtf(outer * outer - dy * dy);
412	    const wide_t xo0 = (wide_t)ceilf(cx - ho - 0.5f);
413	    const wide_t xo1 = (wide_t)floorf(cx + ho - 0.5f);
414	    if (inner <= 0.0f || fabsf(dy) >= inner) {
415	      fill_box(c, xo0, row, xo1, row, colour);
416	      continue;
417	    }
418	    const float hi = sqrtf(inner * inner - dy * dy);
419	    const wide_t xi0 = (wide_t)ceilf(cx - hi - 0.5f);
420	    const wide_t xi1 = (wide_t)floorf(cx + hi - 0.5f);
421	    fill_box(c, xo0, row, xi0 - 1, row, colour);
422	    fill_box(c, xi1 + 1, row, xo1, row, colour);
423	  }
424	}
425	
426	static vec2 direction(const int *from, const int *to) {
427	  const float dx = (float)((wide_t)to[0] - from[0]);
428	  const float dy = (float)((wide_t)to[1] - from[1]);
429	  const float len = sqrtf(dx * dx + dy * dy);
430	  return (vec2){dx / len, dy / len};
431	}
432	
433	void stroke_polyline(Canvas *c, const struct XshimGC *gc, const int *xy, int n,
434	                     int closed) {
435	  if (n <= 0) return;
436	  const int w = gc->line_width;
437	  const uint16_t colour = (uint16_t)gc->foreground;
438	  g_alpha = gc->alpha;
439	
440	  int stack_v[2 * 64];
441	  int *v = stack_v;
442	  if (n > 64) {
443	    v = (int *)malloc((size_t)n * 2 * sizeof(int));
444	    if (!v) return;
445	  }
446	  int m = 0;
447	  for (int i = 0; i < n; i++) {
448	    if (m > 0 && xy[2 * i] == v[2 * (m - 1)] && xy[2 * i + 1] == v[2 * (m - 1) + 1])
449	      continue;
450	    v[2 * m] = xy[2 * i];
451	    v[2 * m + 1] = xy[2 * i + 1];
452	    m++;
453	  }
454	  if (closed && m > 1 && v[2 * (m - 1)] == v[0] && v[2 * (m - 1) + 1] == v[1]) m--;
455	
456	  if (m == 1 || (m == 2 && !closed)) {
457	    stroke_segment(c, gc, v[0], v[1], v[2 * (m - 1)], v[2 * (m - 1) + 1]);
458	  } else {
459	    const int nseg = closed ? m : m - 1;
460	    if (g_alpha) open_mask(c);
461	    for (int i = 0; i < nseg; i++) {
462	      const int *a = v + 2 * i, *b = v + 2 * ((i + 1) % m);
463	      const int cap1 = (!closed && i == 0) ? gc->cap_style : STROKE_NO_CAP;
464	      const int cap2 = (!closed && i == nseg - 1) ? gc->cap_style : STROKE_NO_CAP;
465	      if (cap1 == CapRound) disc(c, a[0], a[1], w, colour);
466	      if (cap2 == CapRound) disc(c, b[0], b[1], w, colour);
467	      segment_quad(c, vertex(a[0], a[1], w), vertex(b[0], b[1], w), cap1, cap2, w,
468	                   colour);
469	    }
470	    const int first = closed ? 0 : 1, last = closed ? m : m - 1;
471	    for (int j = first; j < last; j++) {
472	      const int *prev = v + 2 * ((j + m - 1) % m), *at = v + 2 * j;
473	      const int *next = v + 2 * ((j + 1) % m);
474	      join_at(c, at[0], at[1], direction(prev, at), direction(at, next), w,
475	              gc->join_style, colour);
476	    }
477	    close_mask(c, colour);
478	  }
479	  if (v != stack_v) free(v);
480	}
