#ifndef X11SHIM_STROKE_H
#define X11SHIM_STROKE_H

#include "core/canvas.h"
#include "x11shim/xshim.h"

/* Wide lines (line_width above 1). Width 0 and 1 never come here: they take
 * the plain canvas_line path.
 *
 * Geometry. A vertex (x, y) is the pixel x, y. For an odd width the line runs
 * through that pixel's centre; for an even width it runs through the pixel's
 * top left corner, so the extra pixel falls above and to the left, as in Xlib
 * (an even width starts width / 2 pixels before the vertex). A pixel is drawn
 * when its centre is inside the shape, with the left and top edges excluded and
 * the right and bottom edges included, so a butt cap covers the pixels from the
 * first vertex to the last. */

/* Cap argument meaning "this end meets another segment": no cap, no extension. */
#define STROKE_NO_CAP (-1)

/* One segment with the GC's width and cap style on both ends. */
void stroke_segment(Canvas *c, const struct XshimGC *gc, int x1, int y1, int x2,
                    int y2);

/* As stroke_segment, with a cap style for each end. */
void stroke_segment_ends(Canvas *c, const struct XshimGC *gc, int x1, int y1,
                         int x2, int y2, int cap_start, int cap_end);

/* x0,y0,x1,y1,...: n vertices joined with the GC's join style, and capped at
 * the two ends unless closed. Repeated vertices are ignored. */
void stroke_polyline(Canvas *c, const struct XshimGC *gc, const int *xy, int n,
                     int closed);

/* The outline of the circle XDrawArc would draw for the box x, y, w by w and a
 * full sweep, with the GC's width: a ring, filled a row at a time. The
 * polyline stroke_polyline would draw for the same arc takes about 40 times as
 * many fills. It differs from that polyline only at the pixels on an edge. */
void stroke_circle(Canvas *c, const struct XshimGC *gc, int x, int y, unsigned w);

#endif
"""Flash builds of the firmware in turn and compare their serial logs.

    .venv/bin/python -I tools/ab_flash.py --hack CubicGrid --seconds 60 \\
        --rounds 2 --out /tmp/ab base= iram=-DGL_IRAM "prof=-DGL_PROFILE -DGL_IRAM"

Each `name=flags` is a variant. Every variant is built once, pinned to the
hack with rotation off (`START_HACK`, `ROTATE_SECONDS=0`), and its image kept.
Then, round by round, each image is flashed and the serial log captured for
`--seconds`. A boot is deterministic, so alternating builds and comparing
window by window is how this repo measures a change (AGENTS.md).

This flashes the device: run it only with Rod's go-ahead. It never touches
the partition table or `ffat`; `pio run -t upload` writes what a normal
upload writes.
"""

import argparse
import os
import re
import statistics
import subprocess
import sys
from dataclasses import dataclass, field
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
FIRMWARE = ROOT / "firmware"

RUN = re.compile(r"^run (?P<hack>\S+) (?P<fields>.*)$")
GLPROF = re.compile(r"^glprof (?P<hack>\S+) (?P<fields>.*)$")
FIELD = re.compile(r"(\w+)=([-\d.]+)")


def parse_fields(text: str) -> dict[str, float]:
    """`fps=12.3 step=45.6ms rows=466` to {"fps": 12.3, "step": 45.6, ...}."""
    return {k: float(v) for k, v in FIELD.findall(text)}


@dataclass
class Capture:
    runs: list[dict[str, float]] = field(default_factory=list)
    glprof: list[dict[str, float]] = field(default_factory=list)


def parse_log(text: str, hack: str) -> Capture:
    """The `run` and `glprof` windows a log has for `hack` (any case)."""
    out = Capture()
    for raw in text.splitlines():
        line = raw.strip()
        for pattern, bucket in ((RUN, out.runs), (GLPROF, out.glprof)):
            m = pattern.match(line)
            if m and m.group("hack").lower() == hack.lower():
                bucket.append(parse_fields(m.group("fields")))
    return out


def summarise(windows: list[dict[str, float]], skip: int = 1) -> dict[str, float]:
    """Mean of each field, leaving out the first `skip` windows: the first
    holds the boot and, for push, the name overlay (AGENTS.md)."""
    kept = windows[skip:]

